456	void PhysicsBody::setMass(float mass)
457	{
458	    if (mass <= 0)
459	    {
460	        return;
461	    }
462	
463	    _mass = mass;
464	    _massDefault = false;
465	    _massSetByUser = true;
466	
467	    // update density
468	    if (_mass == PHYSICS_INFINITY)
469	    {
470	        _density = PHYSICS_INFINITY;
471	    }
472	    else
473	    {
474	        if (_area > 0)
475	        {
476	            _density = _mass / _area;
477	        }
478	        else
479	        {
480	            _density = 0;
481	        }
482	    }
483	
484	    // the static body's mass and moment is always infinity
485	    if (_dynamic)
486	    {
487	        internalBodySetMass(_cpBody, _mass);
488	    }
489	}
