538	void PhysicsBody::addMoment(float moment)
539	{
540	    if (moment == PHYSICS_INFINITY)
541	    {
542	        // if moment is infinity, the moment of the body will be infinity
543	        _moment = PHYSICS_INFINITY;
544	        _momentDefault = false;
545	    }
546	    else if (moment == -PHYSICS_INFINITY)
547	    {
548	        return;
549	    }
550	    else
551	    {
552	        if (_momentDefault)
553	        {
554	            _moment = 0;
555	            _momentDefault = false;
556	        }
557	
558	        if (_moment + moment > 0)
559	        {
560	            _moment += moment;
561	        }
562	        else
563	        {
564	            _moment = MOMENT_DEFAULT;
565	            _momentDefault = true;
566	        }
567	    }
568	
569	    // the static body's mass and moment is always infinity
570	    if (_rotationEnabled && _dynamic)
571	    {
572	        cpBodySetMoment(_cpBody, _moment);
573	    }
574	}
